// Unico punto di configurazione: indirizzo interno dell'API e sito pubblico.
const API = 'http://gedosan-api:8080';
const SITO = 'https://gedosan.vszdev.it';

// Il chatId arriva da Telegram (aggiornamento firmato con il token segreto del webhook): è l'unica
// identità di cui il bot si fida. Non viene mai preso dal testo dell'utente né dall'AI.
const u = $json;
if (u.callback_query) {
  const cq = u.callback_query;
  const [azione, valore] = String(cq.data || '').split(':');
  return { json: { api: API, sito: SITO, uscita: 6, chatId: cq.message.chat.id, queryId: cq.id,
    azione, valore: Number(valore) || null, nome: cq.from.first_name || '' } };
}

const m = u.message || {};
const testo = String(m.text || '').trim();
const base = { api: API, sito: SITO, chatId: m.chat && m.chat.id, nome: (m.from && m.from.first_name) || '' };
const esci = (uscita, extra) => ({ json: Object.assign({}, base, { uscita }, extra) });
const messaggio = (testo) => esci(1, { messaggio: testo });

if (!m.chat || m.chat.type !== 'private') return esci(0, {});
if (!testo) return messaggio('Per ora leggo solo messaggi di testo.');

const ESEMPIO = '<code>RSSMRA85M01H501Z, mario.rossi@email.it</code>';
const comando = testo.split(/\s+/)[0].toLowerCase().replace(/@.*$/, '');
if (comando === '/start' || comando === '/aiuto') {
  return messaggio(`Ciao ${base.nome}! Sono l'assistente di Gedosan.\n\n`
    + 'Posso dirti quali centri ci sono, quando sono aperti e se ci sono posti liberi.\n\n'
    + 'Se hai già donato con noi, scrivi /collega: potrai sapere quando puoi donare di nuovo, '
    + 'vedere i tuoi appuntamenti e prenotare da qui.\n\n'
    + `È la tua prima donazione? Prenota dal sito: ${SITO}/prenota`);
}
if (comando === '/collega') {
  return messaggio('Per accedere ai tuoi dati devo verificare chi sei.\n\n'
    + 'Scrivimi in un solo messaggio il tuo codice fiscale e l\'email che hai usato per prenotare, '
    + `separati da una virgola. Esempio:\n${ESEMPIO}\n\n`
    + `Se è la tua prima donazione, prenota dal sito: ${SITO}/prenota`);
}
if (comando === '/esci') return esci(2, {});

// Filtro privacy: messaggi con codice fiscale, email o codici numerici seguono il ramo fisso e non
// arrivano mai all'assistente AI.
const CF = /\b[a-z]{6}[0-9lmnpqrstuv]{2}[a-z][0-9lmnpqrstuv]{2}[a-z][0-9lmnpqrstuv]{3}[a-z]\b/i;
const EMAIL = /[^\s,;]+@[^\s,;]+\.[^\s,;]+/;
const cf = testo.match(CF);
const email = testo.match(EMAIL);
if (cf && email) return esci(3, { cf: cf[0], email: email[0] });
const soloCifre = testo.replace(/\s/g, '');
if (/^\d{6}$/.test(soloCifre)) return esci(4, { codice: soloCifre });
if (cf || email || /\d{6}/.test(soloCifre)) {
  return messaggio('Per proteggere i tuoi dati non passo codici fiscali, email o codici all\'assistente.\n\n'
    + 'Per collegarti scrivi codice fiscale ed email in un solo messaggio, separati da una virgola:\n' + ESEMPIO);
}
return esci(5, { testo });

function testoErrore(r) {
  if (r.statusCode && r.statusCode < 500 && r.body && r.body.messaggio) return r.body.messaggio;
  return 'Il servizio di prenotazione non risponde. Riprova tra qualche minuto.';
}
const n = $('Normalizza').first().json;
const messaggio = $json.statusCode === 204
  ? 'Fatto: questa chat non è più collegata ai tuoi dati. Per ricollegarla scrivi /collega.'
  : testoErrore($json);
return { json: { chatId: n.chatId, messaggio } };

function testoErrore(r) {
  if (r.statusCode && r.statusCode < 500 && r.body && r.body.messaggio) return r.body.messaggio;
  return 'Il servizio di prenotazione non risponde. Riprova tra qualche minuto.';
}
const n = $('Normalizza').first().json;
const messaggio = $json.statusCode === 202 ? $json.body.messaggio : testoErrore($json);
return { json: { chatId: n.chatId, messaggio } };

function testoErrore(r) {
  if (r.statusCode && r.statusCode < 500 && r.body && r.body.messaggio) return r.body.messaggio;
  return 'Il servizio di prenotazione non risponde. Riprova tra qualche minuto.';
}
const n = $('Normalizza').first().json;
let messaggio = testoErrore($json);
if ($json.statusCode === 200) {
  const fino = DateTime.fromISO($json.body.validoFinoAl).setLocale('it').toFormat('d LLLL yyyy');
  messaggio = `✅ Fatto, ciao ${$json.body.nome}! Ora puoi chiedermi quando puoi donare, vedere i tuoi `
    + `appuntamenti o prenotare.\n\nResti collegato fino al ${fino}. Per scollegarti scrivi /esci.`;
}
return { json: { chatId: n.chatId, messaggio } };

const n = $('Normalizza').first().json;
const testo = String($json.output || '');
const proposta = testo.match(/PROPONI_ORARI\|(\d+)\|(\d{4}-\d{2}-\d{2})/);
const escape = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let messaggio = escape(testo.replace(/^.*PROPONI_ORARI.*$/m, '').trim());
if (!testo) messaggio = 'L\'assistente in questo momento non è disponibile. Puoi comunque usare /collega '
  + `e i pulsanti degli orari, oppure prenotare dal sito: ${n.sito}/prenota`;
if (!messaggio && proposta) messaggio = 'Ecco gli orari disponibili.';
return { json: { chatId: n.chatId, api: n.api, messaggio,
  proposta: !!proposta, idTrasfusionale: proposta && Number(proposta[1]), data: proposta && proposta[2] } };

function testoErrore(r) {
  if (r.statusCode && r.statusCode < 500 && r.body && r.body.messaggio) return r.body.messaggio;
  return 'Il servizio di prenotazione non risponde. Riprova tra qualche minuto.';
}
const p = $('Ha proposto orari?').first().json;
if ($json.statusCode !== 200) return { json: { chatId: p.chatId, messaggio: testoErrore($json), pulsanti: [] } };
const liberi = $json.body.filter(s => s.disponibile && s.postiLiberi > 0);
const bottoni = liberi.map(s => ({ text: s.orario.slice(0, 5), callback_data: 'slot:' + s.idSlot }));
const pulsanti = [];
for (let i = 0; i < bottoni.length; i += 4) pulsanti.push(bottoni.slice(i, i + 4));
const giorno = DateTime.fromISO(p.data).setLocale('it').toFormat('cccc d LLLL');
const messaggio = pulsanti.length ? `Orari liberi per ${giorno}: scegline uno.` : `Per ${giorno} non ci sono più orari liberi.`;
return { json: { chatId: p.chatId, messaggio, pulsanti } };

function testoErrore(r) {
  if (r.statusCode && r.statusCode < 500 && r.body && r.body.messaggio) return r.body.messaggio;
  return 'Il servizio di prenotazione non risponde. Riprova tra qualche minuto.';
}
const n = $('Normalizza').first().json;
if ($json.statusCode !== 200) return { json: { chatId: n.chatId, messaggio: testoErrore($json), pulsanti: [] } };
const s = $json.body;
const giorno = DateTime.fromISO(s.data).setLocale('it').toFormat('cccc d LLLL yyyy');
const messaggio = `Confermi la prenotazione?\n\n<b>${s.centro}</b>\n${s.indirizzo}\n${giorno} alle ${s.orario.slice(0, 5)}`;
const pulsanti = [[{ text: '✅ Conferma', callback_data: 'conf:' + s.idSlot }, { text: 'Annulla', callback_data: 'annulla' }]];
return { json: { chatId: n.chatId, messaggio, pulsanti } };

function testoErrore(r) {
  if (r.statusCode && r.statusCode < 500 && r.body && r.body.messaggio) return r.body.messaggio;
  return 'Il servizio di prenotazione non risponde. Riprova tra qualche minuto.';
}
const n = $('Normalizza').first().json;
let messaggio = testoErrore($json);
if ($json.statusCode === 201) {
  const p = $json.body;
  const giorno = DateTime.fromISO(p.data).setLocale('it').toFormat('cccc d LLLL yyyy');
  messaggio = `✅ Prenotato! Ti aspettiamo ${giorno} alle ${p.orario.slice(0, 5)} al ${p.centro} (${p.indirizzo}).\n\n`
    + `Ti abbiamo mandato l'email di conferma; il giorno prima riceverai un promemoria. `
    + `Per annullare o spostare chiama il centro: ${p.telefono}.`;
}
return { json: { chatId: n.chatId, messaggio } };
